SELECT payload FROM digital_team_project_event
WHERE tenant_id = #{tenantId} AND conversation_id = #{conversationId}
AND event_type = 'AGENT_RUN_MARKER' AND sequence > #{afterSequence}
AND payload LIKE CONCAT('%"sessionId":"', #{sessionId}, '"%')
ORDER BY sequence LIMIT 1

SELECT business_id AS id, project_id, conversation_id, message_id, sequence,
event_type, payload, created_at FROM digital_team_project_event
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND visibility = 'PUBLIC' AND conversation_id = #{conversationId}
AND sequence > #{afterSequence} ORDER BY sequence LIMIT #{limit}

SELECT sequence, event_type, payload, created_at FROM digital_team_project_event
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND visibility = 'PUBLIC' AND conversation_id = #{taskId} ORDER BY sequence
